let desktopPage=0,desktopTodos=localRead('desktopTodos',[]),desktopWeather=localRead('desktopWeather',{city:null,data:null,at:0}),desktopWeatherBusy=false,desktopCitySearch=0;
const desktopApps={wechat:['♡','微信'],homeland:['⌂','玫瑰家园'],calendar:['▦','日历'],weather:['☀','天气'],todos:['✓','待办事项'],period:['☾','经期记录'],book:['♧','世界书'],memory:['✧','记忆花园'],stickers:['☺','表情小匣'],api:['⚙','API 设置']};
function palacePetHTML(kind){return `<span class="palace-pet palace-pet-${['cat','dog','bunny'].includes(kind)?kind:'cat'}" role="img" aria-label="${{cat:'奶白猫',dog:'奶白狗',bunny:'宫廷兔'}[kind]||'奶白猫'}"></span>`}
function homePetArt(kind){return palacePetHTML(kind)}
function desktopApp(id){const [icon,n]=desktopApps[id];return `<button class="desk-app desk-app-${id}" data-go="${id}"><span aria-hidden="true">${icon}</span><small>${n}</small></button>`}
function desktopDate(){return new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}
function weatherIcon(kind){return `<svg viewBox="0 0 80 70" aria-hidden="true">${kind==='sun'?'<g stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="40" cy="33" r="15" fill="currentColor" opacity=".18"/><circle cx="40" cy="33" r="15" fill="none"/><path d="M40 8V3m0 60v-5M15 33H9m62 0h-6M22 15l-4-4m44 44-4-4M22 51l-4 4m44-44-4 4"/></g>':`<path d="M19 43a12 12 0 0 1 2-24 19 19 0 0 1 36-1 14 14 0 1 1 3 28H22" fill="currentColor" opacity=".16"/><path d="M19 43a12 12 0 0 1 2-24 19 19 0 0 1 36-1 14 14 0 1 1 3 28H22" fill="none" stroke="currentColor" stroke-width="2"/>${kind==='rain'?'<path d="M27 55l-4 8m20-8-4 8m20-8-4 8" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>':kind==='snow'?'<text x="25" y="65" fill="currentColor" font-size="20">❄</text>':''}`}</svg>`}
function weatherWidget(){const w=desktopWeather,c=w.city,d=w.data,stale=Date.now()-w.at>3600000;return `<button class="desk-widget weather-widget" id="desktopWeather" aria-label="${c?'查看'+escapeHtml(c.name)+'天气':'设置天气城市'}"><div class="widget-overline">WEATHER <span>↗</span></div><div class="weather-symbol">${weatherIcon(d?PalaisDesktop.condition(d.code)[1]:'sun')}</div><strong>${d?d.temperature+'°':'—°'}</strong><b>${escapeHtml(c?.name||'你所在的城市')}</b><small>${d?PalaisDesktop.condition(d.code)[0]+(stale?' · 缓存':''):'点此选择城市'}</small></button>`}
function calendarWidget(){const m=PalaisDesktop.month();return `<button class="desk-widget month-widget" data-go="calendar" aria-label="打开日历"><div class="widget-overline">${m.year} <span>${m.month} 月</span></div><div class="mini-calendar">${['一','二','三','四','五','六','日'].map(n=>`<small>${n}</small>`).join('')}${'<i></i>'.repeat(m.offset)}${Array.from({length:m.days},(_,i)=>`<span class="${i+1===m.today?'is-today':''}">${i+1}</span>`).join('')}</div></button>`}
function todoWidget(){const pending=desktopTodos.filter(t=>!t.done),visible=pending.slice(0,3);return `<section class="desk-widget todo-widget"><div class="todo-widget-heading"><div class="widget-overline">LITTLE THINGS <b>今日待办</b></div><button id="desktopAddTodo" aria-label="添加待办">＋</button></div><div id="desktopTodoRows">${visible.length?visible.map(t=>`<label><input type="checkbox" data-todo="${escapeHtml(t.id)}"><span>${escapeHtml(t.text)}</span></label>`).join(''):'<button class="todo-empty" data-go="todos">写下一件想做的小事…</button>'}</div><button class="todo-all" data-go="todos">${pending.length?pending.length+' 件待完成':'把时间留给喜欢的事'} <span>查看全部 ›</span></button></section>`}
function renderDesktop(){
 document.querySelector('.phone').classList.add('desktop-mode');const pet=PalaisTheme.mascot(),m=PalaisDesktop.month();screen.innerHTML=`<section class="paged-desktop"><header class="desktop-heading"><span>ROSE PALAIS</span><button id="desktopTheme" aria-label="桌面主题设置">✧</button></header><div class="desktop-pages" id="desktopPages" aria-label="手机桌面，可左右翻页" tabindex="0"><section class="desktop-page" aria-label="第 1 页 日常"><div class="desktop-clock"><small>${desktopDate()}</small><div id="bigTime"></div><p>今天，也留一点温柔给自己。</p></div><div class="desktop-duo">${weatherWidget()}<button class="desk-widget companion-widget" id="desktopPet" aria-label="切换桌面宠物"><span class="widget-overline">OUR LITTLE HOME</span><div>${palacePetHTML(pet)}</div><small>有你在的地方，就是家。</small></button></div><div class="desktop-apps">${PalaisDesktop.pages[0].apps.map(desktopApp).join('')}</div><div class="desktop-caption">A SOFT PLACE TO LAND <span>01</span></div></section><section class="desktop-page" aria-label="第 2 页 生活"><div class="desktop-page-title"><small>A LITTLE EVERYDAY</small><h2>把日子，慢慢过。</h2></div>${calendarWidget()}${todoWidget()}<div class="desktop-apps compact-apps">${PalaisDesktop.pages[1].apps.map(desktopApp).join('')}</div></section><section class="desktop-page" aria-label="第 3 页 故事"><div class="desktop-page-title"><small>OUR PRIVATE UNIVERSE</small><h2>故事在这里继续。</h2></div><div class="desk-widget story-widget"><span class="widget-overline">CHAPTER ${String(m.month).padStart(2,'0')}</span><div class="story-ornament">❦</div><p>收藏每一句心事，<br>也收藏每一次相遇。</p><small>THE LITTLE THINGS WE KEEP</small></div><div class="desktop-apps story-apps">${PalaisDesktop.pages[2].apps.map(desktopApp).join('')}</div><button class="desktop-settings" data-go="me">我的小宫殿 <span>人物、主题与备份 ›</span></button></section></div><nav class="desktop-pagination" aria-label="桌面分页">${PalaisDesktop.pages.map((p,i)=>`<button data-desktop-page="${i}" aria-label="第 ${i+1} 页 ${p.name}" ${i===desktopPage?'aria-current="page"':''}><i></i></button>`).join('')}<span id="desktopPageName">${PalaisDesktop.pages[desktopPage].name}</span></nav></section>`;
 time();const scroller=$('#desktopPages');scroller.scrollLeft=desktopPage*scroller.clientWidth;let scheduled=false;scroller.onscroll=()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;desktopPage=Math.max(0,Math.min(2,Math.round(scroller.scrollLeft/scroller.clientWidth)));document.querySelectorAll('[data-desktop-page]').forEach((b,i)=>{if(i===desktopPage)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#desktopPageName').textContent=PalaisDesktop.pages[desktopPage].name})};document.querySelectorAll('[data-desktop-page]').forEach(b=>b.onclick=()=>scroller.scrollTo({left:Number(b.dataset.desktopPage)*scroller.clientWidth,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));scroller.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key)||e.target!==scroller)return;e.preventDefault();const p=Math.max(0,Math.min(2,desktopPage+(e.key==='ArrowRight'?1:-1)));scroller.scrollTo({left:p*scroller.clientWidth,behavior:'smooth'})};
 $('#desktopTheme').onclick=()=>openThemePicker(()=>render());$('#desktopPet').onclick=()=>{PalaisTheme.setMascot(PalaisTheme.nextMascot(PalaisTheme.mascot()),document);$('#desktopPet>div').innerHTML=palacePetHTML(PalaisTheme.mascot())};$('#desktopWeather').onclick=()=>go('weather');$('#desktopAddTodo').onclick=()=>openDesktopTodo();bindDesktopTodoChecks();if(desktopWeather.city&&Date.now()-desktopWeather.at>1800000)refreshDesktopWeather();
}
function bindDesktopTodoChecks(){document.querySelectorAll('[data-todo]').forEach(b=>b.onchange=()=>{try{const next=PalaisDesktop.tasks(desktopTodos,{type:'toggle',id:b.dataset.todo});localSave('desktopTodos',next);desktopTodos=next;if(tab==='home')render();else renderTodos()}catch(e){b.checked=!b.checked;toast(e.message)}})}
function openDesktopTodo(){const d=panel(`<form id="desktopTodoForm"><div class="eyebrow">ONE LITTLE THING</div><h2>添加待办</h2><label>想完成什么？<input name="todoText" required maxlength="80" placeholder="例如：给小花浇水"></label><div class="actions"><button class="secondary" type="button" id="cancelDesktopTodo">取消</button><button class="primary">保存</button></div></form>`);$('#cancelDesktopTodo').onclick=()=>d.close();d.querySelector('form').onsubmit=e=>{e.preventDefault();try{const next=PalaisDesktop.tasks(desktopTodos,{type:'add',id:crypto.randomUUID(),text:e.target.todoText.value,now:Date.now()});localSave('desktopTodos',next);desktopTodos=next;d.close();if(tab==='home')render();else renderTodos();toast('待办已保存')}catch(e){toast(e.message)}}}
function renderTodos(){screen.innerHTML=`<section class="view todos-view">${title('待办事项','ONE THING AT A TIME','<button class="round" id="newDesktopTodo" aria-label="添加待办">＋</button>')}<button class="text-button" data-go="home">‹ 回到桌面</button><p class="section-note">${desktopTodos.filter(t=>!t.done).length} 件待完成 · 小事也值得被记住</p><div class="todos-list">${desktopTodos.length?desktopTodos.map(t=>`<label class="todo-item ${t.done?'completed':''}"><input type="checkbox" data-todo="${escapeHtml(t.id)}" ${t.done?'checked':''}><span>${escapeHtml(t.text)}</span></label>`).join(''):'<div class="soft-empty">还没有待办，写下今天想做的一件小事吧。</div>'}</div></section>`;$('#newDesktopTodo').onclick=openDesktopTodo;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));bindDesktopTodoChecks()}
function renderWeather(){const w=desktopWeather,d=w.data;screen.innerHTML=`<section class="view weather-view">${title('天气','A LITTLE SKY ABOVE YOU')}<button class="text-button" data-go="home">‹ 回到桌面</button><div class="weather-detail">${weatherIcon(d?PalaisDesktop.condition(d.code)[1]:'cloud')}<h3>${escapeHtml(w.city?.name||'选择一座城市')}</h3><strong>${d?d.temperature+'°':'—°'}</strong><p>${d?PalaisDesktop.condition(d.code)[0]:'设置城市后显示当地天气'}</p><small>${d&&Number.isFinite(d.high)&&Number.isFinite(d.low)?'最高 '+Math.round(d.high)+'° · 最低 '+Math.round(d.low)+'°':''}</small>${w.at?`<small>最近更新 ${new Date(w.at).toLocaleString('zh-CN')}</small>`:''}</div><button class="secondary full" id="refreshDesktopWeather" ${!w.city||desktopWeatherBusy?'disabled':''}>${desktopWeatherBusy?'正在获取…':'刷新天气'}</button><form id="weatherCityForm"><label>城市<input name="city" maxlength="60" required placeholder="输入城市，例如上海"></label><button class="primary full">搜索城市</button></form><div id="weatherCityResults" aria-live="polite"></div><p class="section-note">天气来自 <a href="https://open-meteo.com/" target="_blank" rel="noopener">Open-Meteo</a>，为模型估算数据。<br>只使用你选择的城市，不请求定位权限。<br>网络不可用时保留上次天气及更新时间。</p></section>`;document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('#refreshDesktopWeather').onclick=()=>refreshDesktopWeather(true);$('#weatherCityForm').onsubmit=searchDesktopCity}
async function searchDesktopCity(e){e.preventDefault();const city=e.target.city.value.trim(),ticket=++desktopCitySearch,results=$('#weatherCityResults'),button=e.target.querySelector('button');if(city.length<2){toast('请至少输入两个字');return}button.disabled=true;results.textContent='正在搜索城市…';try{const u=new URL('https://geocoding-api.open-meteo.com/v1/search');u.search=new URLSearchParams({name:city,count:6,language:'zh',format:'json'});const res=await fetch(u,{signal:AbortSignal.timeout(15000)});if(!res.ok)throw Error('城市搜索暂不可用');const data=await res.json();if(ticket!==desktopCitySearch||!results.isConnected)return;const locations=(data.results||[]).filter(c=>Number.isFinite(c.latitude)&&Number.isFinite(c.longitude));results.innerHTML=locations.length?locations.map((c,i)=>`<button class="city-result" data-city-index="${i}">${escapeHtml(c.name)}<small>${escapeHtml([c.admin1,c.country].filter(Boolean).join(' · '))}</small></button>`).join(''):'没有找到城市，可以尝试英文名或附近城市。';results.querySelectorAll('[data-city-index]').forEach(b=>b.onclick=()=>{const c=locations[Number(b.dataset.cityIndex)],next={city:{name:c.name,latitude:c.latitude,longitude:c.longitude},data:null,at:0};try{localSave('desktopWeather',next);desktopWeather=next;renderWeather();refreshDesktopWeather(true)}catch{toast('城市保存失败')}})}catch{if(results.isConnected)results.textContent='城市搜索失败，请检查网络后重试。'}finally{if(button.isConnected)button.disabled=false}}
async function refreshDesktopWeather(force=false){if(!desktopWeather.city||desktopWeatherBusy||!force&&Date.now()-desktopWeather.at<1800000)return;const city=desktopWeather.city;desktopWeatherBusy=true;if(tab==='weather')renderWeather();try{const u=new URL('https://api.open-meteo.com/v1/forecast');u.search=new URLSearchParams({latitude:city.latitude,longitude:city.longitude,current:'temperature_2m,weather_code',daily:'temperature_2m_max,temperature_2m_min',timezone:'auto',forecast_days:1});const res=await fetch(u,{signal:AbortSignal.timeout(15000)});if(!res.ok)throw Error('天气服务暂不可用');const data=PalaisDesktop.weather(await res.json());if(city!==desktopWeather.city)return;const next={city,data,at:Date.now()};localSave('desktopWeather',next);desktopWeather=next}catch{if(tab==='weather')toast('天气更新失败，稍后可重试')}finally{desktopWeatherBusy=false;if(city!==desktopWeather.city&&desktopWeather.city){refreshDesktopWeather(true);return}if(tab==='weather')renderWeather();else if(tab==='home'&&$('#desktopWeather')){const box=document.createElement('div');box.innerHTML=weatherWidget();$('#desktopWeather').replaceWith(box.firstElementChild);$('#desktopWeather').onclick=()=>go('weather')}}}
